import "../css/mainPage.css";

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import logo from "../image/tybwhitelogo.png";
import logoblack from "../image/tyblogoblack.jpeg";
import esign1 from "../image/georgeEsign.jpeg";

import DashboardIcon from "@mui/icons-material/Dashboard";
import PrintIcon from "@mui/icons-material/Print";

const units = ["kg", "gms", "pcs"];

const API_BASE_URL = "http://localhost:5000";

const msme = process.env.REACT_APP_MSME;

function MainPage() {
    const navigate = useNavigate();

    // ============================================================
    // BILL TYPE
    // ============================================================

    const [billType, setBillType] = useState("resort");

    // ============================================================
    // RESORT CUSTOMER BILLING
    // ============================================================

    const [resortCustomers, setResortCustomers] = useState([]);
    const [resortProducts, setResortProducts] = useState([]);

    const [resortCustomer, setResortCustomer] = useState("");
    const [resortProduct, setResortProduct] = useState("");
    const [resortQuantity, setResortQuantity] = useState(1);

    const [resortCart, setResortCart] = useState([]);

    // ============================================================
    // STORE CUSTOMER BILLING
    // ============================================================

    const [storeProducts, setStoreProducts] = useState([]);

    const [storeCustomerName, setStoreCustomerName] = useState("");
    const [storeCustomerAddress, setStoreCustomerAddress] =
        useState("");

    const [storeProduct, setStoreProduct] = useState("");
    const [storeQuantity, setStoreQuantity] = useState(1);
    const [storeUnit, setStoreUnit] = useState("");
    const [storePrice, setStorePrice] = useState("");

    const [storeCart, setStoreCart] = useState([]);

    // ============================================================
    // COMMON BILL DETAILS
    // ============================================================

    const [billNo, setBillNo] = useState(1);
    const [balance, setBalance] = useState("");

    const [isManual, setIsManual] = useState(false);
    const [selectedDate, setSelectedDate] = useState("");

    const [savingOrder, setSavingOrder] = useState(false);
    const [orderSaved, setOrderSaved] = useState(false);

    // ============================================================
    // DATE
    // ============================================================

    const getTodayDate = () => {
        const currentDate = new Date();

        return currentDate
            .toISOString()
            .split("T")[0];
    };

    const todayDate = getTodayDate();

    useEffect(() => {
        if (!isManual) {
            setSelectedDate(todayDate);
        }
    }, [isManual, todayDate]);

    // ============================================================
    // FETCH RESORT CUSTOMERS
    // ============================================================

    useEffect(() => {
        fetchResortCustomers();
    }, []);

    const fetchResortCustomers = async () => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch resort customers"
                );
            }

            const data = await response.json();

            setResortCustomers(data);
        } catch (error) {
            console.error(
                "Error fetching resort customers:",
                error
            );
        }
    };

    // ============================================================
    // FETCH STORE PRODUCTS
    // ============================================================

    useEffect(() => {
        fetchStoreProducts();
    }, []);

    const fetchStoreProducts = async () => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/store-customers/products`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch store products"
                );
            }

            const data = await response.json();

            setStoreProducts(data);
        } catch (error) {
            console.error(
                "Error fetching store products:",
                error
            );

            setStoreProducts([]);
        }
    };

    // ============================================================
    // FETCH PRODUCTS FOR SELECTED RESORT
    // ============================================================

    const fetchResortProducts = async (customerId) => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers/${customerId}/products`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch products for resort"
                );
            }

            const data = await response.json();

            setResortProducts(data);
        } catch (error) {
            console.error(
                "Error fetching resort products:",
                error
            );

            setResortProducts([]);
        }
    };

    // ============================================================
    // CHANGE BILL TYPE
    // ============================================================

    const handleBillTypeChange = (type) => {
        if (savingOrder) {
            return;
        }

        setBillType(type);

        // Clear resort data
        setResortCustomer("");
        setResortProduct("");
        setResortQuantity(1);
        setResortProducts([]);
        setResortCart([]);

        // Clear store data
        setStoreCustomerName("");
        setStoreCustomerAddress("");
        setStoreProduct("");
        setStoreQuantity(1);
        setStoreUnit("");
        setStorePrice("");
        setStoreCart([]);

        setBalance("");
        setOrderSaved(false);
    };

    // ============================================================
    // RESORT CUSTOMER CHANGE
    // ============================================================

    const handleResortCustomerChange = async (e) => {
        const customerId = e.target.value;

        setResortCustomer(customerId);
        setResortProduct("");
        setResortQuantity(1);
        setOrderSaved(false);

        if (!customerId) {
            setResortProducts([]);
            return;
        }

        await fetchResortProducts(customerId);
    };

    // ============================================================
    // SELECTED RESORT CUSTOMER
    // ============================================================

    const selectedResortCustomer =
        resortCustomers.find(
            (c) =>
                String(c.resort_customer_id) ===
                String(resortCustomer)
        );

    // ============================================================
    // SELECTED RESORT PRODUCT
    // ============================================================

    const selectedResortProduct =
        resortProducts.find((p) => {
            if (
                p.combo_id !== null &&
                p.combo_id !== undefined
            ) {
                return (
                    `combo-${p.combo_id}` ===
                    resortProduct
                );
            }

            return (
                `variant-${p.product_variant_id}` ===
                resortProduct
            );
        });

    // ============================================================
    // RESORT PRICE
    // ============================================================

    const resortUnitPrice = selectedResortProduct
        ? Number(selectedResortProduct.price)
        : 0;

    const resortItemTotal =
        resortUnitPrice *
        Number(resortQuantity || 0);

    // ============================================================
    // ADD RESORT ITEM
    // ============================================================

    const handleAddResortItem = () => {
        if (!resortCustomer) {
            alert("Please select a resort customer.");
            return;
        }

        if (!resortProduct) {
            alert("Please select a product.");
            return;
        }

        if (
            !resortQuantity ||
            Number(resortQuantity) <= 0
        ) {
            alert("Please enter a valid quantity.");
            return;
        }

        if (!selectedResortProduct) {
            alert("Product details not found.");
            return;
        }

        const newItem = {
            id: Date.now(),

            resortCustomerId:
                Number(resortCustomer),

            productVariantId:
                selectedResortProduct
                    .product_variant_id ??
                null,

            comboId:
                selectedResortProduct.combo_id ??
                null,

            product:
                selectedResortProduct.product_name ||
                selectedResortProduct.combo_name,

            packSize:
                selectedResortProduct
                    .pack_size_grams ??
                null,

            quantity:
                Number(resortQuantity),

            price:
                Number(selectedResortProduct.price),

            total:
                Number(selectedResortProduct.price) *
                Number(resortQuantity)
        };

        setResortCart((prevCart) => [
            ...prevCart,
            newItem
        ]);

        setResortProduct("");
        setResortQuantity(1);
        setOrderSaved(false);
    };

    // ============================================================
    // DELETE RESORT ITEM
    // ============================================================

    const handleDeleteResortItem = (id) => {
        setResortCart((prevCart) =>
            prevCart.filter(
                (item) => item.id !== id
            )
        );

        setOrderSaved(false);
    };


    // ============================================================
    // SELECTED STORE PRODUCT
    // ============================================================

    const selectedStoreProduct =
        storeProducts.find(
            (p) =>
                String(p.product_id) ===
                String(storeProduct)
        );

    // ============================================================
    // STORE TOTAL CALCULATION
    //
    // kg:
    // price entered is per kg
    //
    // gms:
    // price entered is per kg
    //
    // pcs:
    // price entered is per piece
    // ============================================================

    let storeItemTotal = 0;

    if (storeUnit === "gms") {
        storeItemTotal =
            (Number(storeQuantity || 0) / 1000) *
            Number(storePrice || 0);
    } else {
        storeItemTotal =
            Number(storeQuantity || 0) *
            Number(storePrice || 0);
    }

    // ============================================================
    // ADD STORE ITEM
    // ============================================================

    const handleAddStoreItem = () => {
        if (!storeCustomerName.trim()) {
            alert("Please enter the customer name.");
            return;
        }

        if (!storeCustomerAddress.trim()) {
            alert("Please enter the customer address.");
            return;
        }

        if (!storeProduct) {
            alert("Please select a product.");
            return;
        }

        if (
            !storeQuantity ||
            Number(storeQuantity) <= 0
        ) {
            alert("Please enter a valid quantity.");
            return;
        }

        if (!storeUnit) {
            alert("Please select a unit.");
            return;
        }

        if (
            storePrice === "" ||
            Number(storePrice) < 0
        ) {
            alert("Please enter a valid price.");
            return;
        }

        if (!selectedStoreProduct) {
            alert("Product details not found.");
            return;
        }

        const newItem = {
            id: Date.now(),

            productId:
                Number(
                    selectedStoreProduct.product_id
                ),

            product:
                selectedStoreProduct.product_name,

            quantity:
                Number(storeQuantity),

            unit:
                storeUnit,

            price:
                Number(storePrice),

            total:
                Number(storeItemTotal)
        };

        setStoreCart((prevCart) => [
            ...prevCart,
            newItem
        ]);

        setStoreProduct("");
        setStoreQuantity(1);
        setStoreUnit("");
        setStorePrice("");
        setOrderSaved(false);
    };

    // ============================================================
    // DELETE STORE ITEM
    // ============================================================

    const handleDeleteStoreItem = (id) => {
        setStoreCart((prevCart) =>
            prevCart.filter(
                (item) => item.id !== id
            )
        );

        setOrderSaved(false);
    };

    // ============================================================
    // STORE CUSTOMER / BILL TOTAL
    // ============================================================

    const itemCart =
        billType === "resort"
            ? resortCart
            : storeCart;

    const itemsTotal =
        billType === "resort"
            ? resortCart.reduce(
                  (sum, item) =>
                      sum + Number(item.total),
                  0
              )
            : storeCart.reduce(
                  (sum, item) =>
                      sum + Number(item.total),
                  0
              );

    const balanceAmount =
        Number(balance || 0);

    const grandTotal =
        itemsTotal + balanceAmount;

    // ============================================================
    // SAVE RESORT ORDER
    // ============================================================

    const saveResortOrder = async () => {
        if (!resortCustomer) {
            return true;
        }

        if (resortCart.length === 0) {
            return true;
        }

        if (orderSaved) {
            return true;
        }

        try {
            setSavingOrder(true);

            const items =
                resortCart.map((item) => ({
                    productVariantId:
                        item.productVariantId,

                    comboId:
                        item.comboId,

                    quantity:
                        item.quantity,

                    /*
                     * IMPORTANT:
                     *
                     * price in order_item is TOTAL
                     * price for this item.
                     *
                     * Example:
                     * quantity = 2
                     * unit price = 235
                     * order_item.price = 470
                     */
                    price:
                        Number(item.price) *
                        Number(item.quantity)
                }));

            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers/${resortCustomer}/orders`,
                {
                    method: "POST",

                    headers: {
                        "Content-Type":
                            "application/json"
                    },

                    body: JSON.stringify({
                        orderDate:
                            selectedDate,

                        totalAmount:
                            Number(grandTotal),

                        items
                    })
                }
            );

            const data =
                await response.json();

            if (!response.ok) {
                throw new Error(
                    data.message ||
                        "Failed to save resort order"
                );
            }

            console.log(
                "Resort order saved:",
                data
            );

            setOrderSaved(true);

            return true;
        } catch (error) {
            console.error(
                "Error saving resort order:",
                error
            );

            alert(
                "Failed to save the resort order. Please try again."
            );

            return false;
        } finally {
            setSavingOrder(false);
        }
    };

    // ============================================================
    // SAVE STORE CUSTOMER ORDER
    // ============================================================

    const saveStoreOrder = async () => {
        if (!storeCustomerName.trim()) {
            return true;
        }

        if (storeCart.length === 0) {
            return true;
        }

        if (orderSaved) {
            return true;
        }

        try {
            setSavingOrder(true);

            const items =
                storeCart.map((item) => ({
                    productId:
                        item.productId,

                    quantity:
                        item.quantity,

                    unit:
                        item.unit,

                    /*
                     * IMPORTANT:
                     *
                     * order_item.price stores the TOTAL
                     * price for the item.
                     *
                     * Example:
                     * 2 kg × ₹500 = ₹1000
                     * price sent = 1000
                     *
                     * Example:
                     * 500 g × ₹500/kg = ₹250
                     * price sent = 250
                     */
                    price:
                        Number(item.total)
                }));

            const response = await fetch(
                `${API_BASE_URL}/api/store-customers/orders`,
                {
                    method: "POST",

                    headers: {
                        "Content-Type":
                            "application/json"
                    },

                    body: JSON.stringify({
                        customerName:
                            storeCustomerName.trim(),

                        address:
                            storeCustomerAddress.trim(),

                        orderDate:
                            selectedDate,

                        totalAmount:
                            Number(grandTotal),

                        items
                    })
                }
            );

            const data =
                await response.json();

            if (!response.ok) {
                throw new Error(
                    data.message ||
                        "Failed to save store order"
                );
            }

            console.log(
                "Store order saved:",
                data
            );

            setOrderSaved(true);


            return true;
        } catch (error) {
            console.error(
                "Error saving store order:",
                error
            );

            alert(
                "Failed to save the store order. Please try again."
            );

            return false;
        } finally {
            setSavingOrder(false);
        }
    };

    // ============================================================
    // SAVE CURRENT ORDER
    // ============================================================

    const saveCurrentOrder = async () => {
        if (billType === "resort") {
            return await saveResortOrder();
        }

        return await saveStoreOrder();
    };

    // ============================================================
    // NEW BILL
    // ============================================================

    const handleNewBill = () => {
        if (savingOrder) {
            return;
        }

        // Resort
        setResortCustomer("");
        setResortProduct("");
        setResortQuantity(1);
        setResortProducts([]);
        setResortCart([]);

        // Store
        setStoreCustomerName("");
        setStoreCustomerAddress("");
        setStoreProduct("");
        setStoreQuantity(1);
        setStoreUnit("");
        setStorePrice("");
        setStoreCart([]);

        setBalance("");
        setOrderSaved(false);
        setSavingOrder(false);

        setBillNo((prev) => prev + 1);
    };

    // ============================================================
    // NUMBER TO WORDS
    // ============================================================

    function numberToWords(num) {
        const ones = [
            "",
            "One",
            "Two",
            "Three",
            "Four",
            "Five",
            "Six",
            "Seven",
            "Eight",
            "Nine",
            "Ten",
            "Eleven",
            "Twelve",
            "Thirteen",
            "Fourteen",
            "Fifteen",
            "Sixteen",
            "Seventeen",
            "Eighteen",
            "Nineteen"
        ];

        const tens = [
            "",
            "",
            "Twenty",
            "Thirty",
            "Forty",
            "Fifty",
            "Sixty",
            "Seventy",
            "Eighty",
            "Ninety"
        ];

        function convert(n) {
            if (n === 0) {
                return "";
            }

            if (n < 20) {
                return ones[n];
            }

            if (n < 100) {
                return (
                    tens[Math.floor(n / 10)] +
                    " " +
                    ones[n % 10]
                );
            }

            if (n < 1000) {
                return (
                    ones[Math.floor(n / 100)] +
                    " Hundred " +
                    convert(n % 100)
                );
            }

            if (n < 100000) {
                return (
                    convert(
                        Math.floor(n / 1000)
                    ) +
                    " Thousand " +
                    convert(n % 1000)
                );
            }

            if (n < 10000000) {
                return (
                    convert(
                        Math.floor(n / 100000)
                    ) +
                    " Lakh " +
                    convert(n % 100000)
                );
            }

            return (
                convert(
                    Math.floor(n / 10000000)
                ) +
                " Crore " +
                convert(n % 10000000)
            );
        }

        if (!num || num === 0) {
            return "Zero Only";
        }

        return (
            convert(Math.floor(num)) +
            " Only"
        );
    }

