                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                {
                                                    item.quantity
                                                }
                                            </td>

                                            <td
                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                ₹
                                                {
                                                    item.price
                                                }
                                            </td>

                                            <td
                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                ₹
                                                {
                                                    item.total
                                                }
                                            </td>

                                        </tr>

                                    )
                                )}

                            {/* =================================================
                                STORE ITEMS
                            ================================================= */}

                            {billType ===
                                "store" &&
                                storeCart.map(
                                    (
                                        item,
                                        index
                                    ) => (

                                        <tr
                                            key={
                                                item.id
                                            }
                                            className="itemDisplay"
                                        >

                                            <td
                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                {
                                                    index +
                                                    1
                                                }
                                            </td>

                                            <td
                                                style={{
                                                    paddingLeft:
                                                        "5px"
                                                }}
                                            >
                                                {
                                                    item.product
                                                }
                                            </td>

                                            <td
                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                {
                                                    item.quantity
                                                }
                                                {
                                                    item.unit
                                                }
                                            </td>

                                            <td
                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                ₹
                                                {
                                                    item.price
                                                }

                                                {item.unit ===
                                                "gms"
                                                    ? " / kg"
                                                    : item.unit ===
                                                      "kg"
                                                    ? " / kg"
                                                    : " / pcs"}
                                            </td>

                                            <td
                                                style={{
                                                    textAlign:
                                                        "center"
                                                }}
                                            >
                                                ₹
                                                {
                                                    item.total
                                                }
                                            </td>

                                        </tr>

                                    )
                                )}

                            {/* =================================================
                                BALANCE
                            ================================================= */}

                            {balanceAmount >
                                0 && (

                                <tr>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        {
                                            balanceSNo
                                        }
                                    </td>

                                    <td
                                        style={{
                                            paddingLeft:
                                                "5px"
                                        }}
                                    >
                                        Balance
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                        colSpan={
                                            2
                                        }
                                    >
                                        ₹
                                        {
                                            balanceAmount
                                        }
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        ₹
                                        {
                                            balanceAmount
                                        }
                                    </td>

                                </tr>

                            )}

                        </tbody>

                    </table>

                    {/* =================================================
                        AMOUNT
                    ================================================= */}

                    <table className="amtTable">

                        <tbody>

                            <tr>

                                <td
                                    style={{
                                        paddingLeft:
                                            "5px"
                                    }}
                                >

                                    <span
                                        style={{
                                            fontWeight:
                                                "bold"
                                        }}
                                    >
                                        Amount in words:
                                    </span>

                                    {" "}

                                    {
                                        numberToWords(
                                            grandTotal
                                        )
                                    }

                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px",
                                        textAlign:
                                            "center",
                                        borderRight:
                                            "1px white solid",
                                        fontWeight:
                                            "bold"
                                    }}
                                >
                                    Grand Total
                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px",
                                        textAlign:
                                            "center"
                                    }}
                                >
                                    {
                                        grandTotal
                                    }
                                </td>

                            </tr>

                        </tbody>

                    </table>

                    {/* =================================================
                        FOOTER
                    ================================================= */}

                    <div className="footer">

                        <div className="terms">

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                Terms & Condition
                                <sup>
                                    *
                                </sup>
                            </span>

                            <br />

                            Payment must be paid
                            within 15 days
                            from the issue
                            of bill.

                        </div>

                        <div className="signature">

                            <img
                                src={
                                    esign1
                                }
                                style={{
                                    width:
                                        "70px",
                                    marginLeft:
                                        "350px"
                                }}
                                alt="signature"
                            />

                            <br />

                            Signature

                        </div>

                    </div>

                </div>

            </div>

        </div>
    );
}

export default MainPage;
